def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    result = v2 - v1

    return {
        "value": result,
        "trace": {
            "v1": v1,
            "v2": v2,
            "difference": result,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": None
            }
        }
    }
